package org.eclipse.rdf4j.workbench.commands;

import static org.assertj.core.api.Assertions.assertThat;
import static org.eclipse.rdf4j.workbench.commands.WorkbenchNativeQueryAssertions.bag;

import java.util.List;
import java.util.Map;
import java.util.function.Supplier;

import org.eclipse.rdf4j.common.iteration.CloseableIteration;
import org.eclipse.rdf4j.query.BindingSet;

/** Test utility for proving that an unordered limited result is a bag subset of its unsliced reference query. */
final class NativeQueryResultBagWitness {

	private NativeQueryResultBagWitness() {
	}

	static void assertContained(List<BindingSet> actual,
			Supplier<? extends CloseableIteration<? extends BindingSet>> referenceRows, String label) {
		Map<BindingSet, Long> remaining = bag(actual);
		try (CloseableIteration<? extends BindingSet> rows = referenceRows.get()) {
			while (!remaining.isEmpty() && rows.hasNext()) {
				BindingSet row = rows.next();
				Long count = remaining.get(row);
				if (count == null) {
					continue;
				}
				if (count == 1) {
					remaining.remove(row);
				} else {
					remaining.put(row, count - 1);
				}
			}
		}
		assertThat(remaining).as("%s: projected candidates must have enough reference multiplicity", label).isEmpty();
	}
}
